<script setup lang="ts">
import {t as tr} from "../i18n";
import {computed,nextTick,onMounted,onUnmounted,ref} from 'vue';
import {useSessionStore} from '../stores/session';import {useBusinessStore} from '../stores/business';import {useRunStore} from '../stores/run';
import {useSidebar} from '../composables/useSidebar';import {useCollection} from '../composables/useCollection';
import {useModal} from '../composables/useModal';
import UiIcon from './UiIcon.vue';import NativeWorkPanel from './NativeWorkPanel.vue';import ScheduledJobsPanel from './ScheduledJobsPanel.vue';import EvidencePanel from './EvidencePanel.vue';import BusinessConnectionPanel from './BusinessConnectionPanel.vue';import SourceBadge from './SourceBadge.vue';
import {TASK_STATUS_LABELS} from '@shared/operations-contract';import type {TaskStatus} from '@shared/operations-contract';
import type {ActorRole} from '../actor';
const props=defineProps<{open:boolean;taskMode:boolean;authMode:'native'|'demo';actor:ActorRole;tasks:Array<{taskId:string;conversationId:string|null;goal:string;status:TaskStatus}>}>();
const emit=defineEmits<{new:[mode?:'chat'|'task'];select:[id:string];rename:[id:string,title:string];remove:[id:string,title:string];rooms:[];task:[id:string|null];actor:[role:ActorRole];logout:[];settings:[];close:[]}>();
const session=useSessionStore(),business=useBusinessStore(),run=useRunStore(),layout=useSidebar(),query=ref(''),search=ref<HTMLInputElement>(),accountOpen=ref(false),detailsOpen=ref(false),more=ref('');
const owner=()=>business.profile?business.profile.identity+':'+business.profile.username:props.authMode==='demo'?'demo:'+props.actor:'';
const pins=useCollection('conversations',owner);
useModal(accountOpen,'.sidebar-account-menu');
const folded=ref({work:false,chat:false});try{const saved=JSON.parse(localStorage.getItem('labops.nav.folded')||'{}');folded.value={work:saved.work===true,chat:saved.chat===true};}catch{}
function fold(key:'work'|'chat'){folded.value[key]=!folded.value[key];try{localStorage.setItem('labops.nav.folded',JSON.stringify(folded.value));}catch{}}
const groups=computed(()=>[{key:'work' as const,label:'工作会话',mode:'task' as const,list:session.workConversations},{key:'chat' as const,label:'聊天会话',mode:'chat' as const,list:session.chatConversations}].map(group=>({...group,list:group.list.filter(c=>!query.value||[c.title,c.preview||''].join(' ').toLowerCase().includes(query.value.toLowerCase())).slice().sort((a,b)=>Number(pins.ids.value.includes(b.id))-Number(pins.ids.value.includes(a.id)))})));
const name=computed(()=>business.profile?.username||'演示账户'),role=computed(()=>({admin:'管理员',volunteer:'志愿者',student:'学生'}[business.profile?.identity||props.actor]));
async function focusSearch(){if(layout.collapsed.value)layout.toggle();await nextTick();search.value?.focus();}
function shortcut(event:KeyboardEvent){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();void focusSearch();}if(event.key==='Escape'){accountOpen.value=false;more.value='';emit('close');}}
onMounted(()=>window.addEventListener('keydown',shortcut));onUnmounted(()=>window.removeEventListener('keydown',shortcut));
</script>
<template>
<aside class="agent-sidebar" :class="{'is-collapsed':layout.collapsed.value,'is-open':open,'is-resizing':layout.resizing.value}" :style="{'--sidebar-size':layout.effectiveWidth.value+'px'}" :aria-label="tr('会话导航')">
 <header class="sidebar-brand"><UiIcon name="lab"/><b>LabOps</b><button :aria-label="layout.collapsed.value?'展开侧边栏':'收起侧边栏'" :title="layout.collapsed.value?'展开侧边栏':'收起侧边栏'" @click="layout.toggle"><UiIcon name="panel"/></button></header>
 <div class="sidebar-shortcuts"><button class="sidebar-new" :disabled="run.inputLocked" @click="emit('new')" :aria-label="tr('新建会话')" :title="tr('新建会话')"><UiIcon name="new"/><span>{{tr("新会话")}}</span></button><button class="sidebar-search-icon" :aria-label="tr('搜索会话')" :title="tr('搜索会话')" @click="focusSearch"><UiIcon name="search"/><span>{{tr("搜索会话")}}</span></button><label class="sidebar-search"><UiIcon name="search"/><input ref="search" v-model="query" type="search" :placeholder="tr('搜索会话')" :aria-label="tr('搜索会话')"></label></div>
 <nav class="sidebar-tools" :aria-label="tr('常用业务')"><NativeWorkPanel :navigation="true" :icon-only="layout.collapsed.value" :readonly="!taskMode"/><button class="sidebar-link" @click="emit('rooms')" :aria-label="tr('实验室')" :title="tr('实验室')"><UiIcon name="room"/><span>{{tr("实验室")}}</span></button><ScheduledJobsPanel :navigation="true" :icon-only="layout.collapsed.value" :readonly="!taskMode"/><EvidencePanel :navigation="true" :icon-only="layout.collapsed.value" :readonly="!taskMode"/></nav>
 <div class="sidebar-history"><p v-if="session.listError" class="sidebar-error" role="alert">{{session.listError}}</p><section v-for="group in groups" :key="group.key" class="sidebar-group"><h2><button :aria-expanded="!folded[group.key]||!!query" @click="fold(group.key)"><UiIcon name="chevron" :size="12" :class="{'is-turned':!folded[group.key]}"/>{{tr(group.label)}}</button><span>{{group.list.length}}</span><button :aria-label="tr('新建'+group.label)" :disabled="run.inputLocked" @click="emit('new',group.mode)"><UiIcon name="new" :size="14"/></button></h2><ul v-if="!folded[group.key]||query" :id="'nav-'+group.key+'-list'"><li v-for="c in group.list" :key="c.id" :class="{'is-active':c.id===session.currentId}"><button class="sidebar-conversation" :title="c.title+'（'+c.messageCount+' 条消息）'" @click="emit('select',c.id)"><UiIcon v-if="pins.ids.value.includes(c.id)" name="star" :size="12"/><span>{{c.title}}</span></button><button class="sidebar-more" :aria-label="tr('管理会话')+': '+c.title" @click="more=more===c.id?'':c.id"><UiIcon name="more" :size="16"/></button><div v-if="more===c.id" class="sidebar-row-menu"><button @click="pins.toggle(c.id);more=''">{{tr(pins.ids.value.includes(c.id)?'取消置顶':'置顶会话')}}</button><button @click="emit('rename',c.id,c.title);more=''">{{tr("重命名")}}</button><button @click="emit('remove',c.id,c.title);more=''">{{tr("删除")}}</button></div></li><li v-if="!group.list.length" class="sidebar-empty">{{tr(query?'无匹配会话':'暂无会话')}}</li></ul></section><section v-if="authMode==='demo'&&tasks.length" class="sidebar-group"><h2>{{tr("我的任务")}}</h2><ul><li v-for="task in tasks.slice(0,12)" :key="task.taskId"><button class="sidebar-conversation" @click="emit('task',task.conversationId)" :title="TASK_STATUS_LABELS[task.status]+' · '+task.goal"><span>{{task.goal}}</span></button></li></ul></section></div>
 <footer class="sidebar-footer"><button class="sidebar-account" :aria-label="tr('账户与设置')" :title="name+' · '+role" @click="accountOpen=!accountOpen"><span class="sidebar-avatar">{{name.slice(0,1).toUpperCase()}}</span><span class="sidebar-account-name"><b>{{name}}</b><small>{{tr(role)}}</small></span><UiIcon name="more"/></button></footer>
 <div class="sidebar-resizer" role="separator" tabindex="0" :aria-label="tr('调整侧边栏宽度')" aria-orientation="vertical" :aria-valuenow="layout.effectiveWidth.value" :aria-valuemin="56" :aria-valuemax="360" :title="tr('长按拖动调整宽度')" @pointerdown="layout.down" @pointermove="layout.move" @pointerup="layout.stop" @pointercancel="layout.stop" @lostpointercapture="layout.stop" @keydown="layout.key"/>
</aside>
<Teleport to="body"><div v-if="accountOpen" class="sidebar-account-mask" @click.self="accountOpen=false"><section class="sidebar-account-menu" role="dialog" aria-modal="true" :aria-label="tr('账户设置')" :style="{'--sidebar-size':layout.effectiveWidth.value+'px'}"><header><b>{{name}} · {{tr(role)}}</b><button :aria-label="tr('关闭账户设置')" @click="accountOpen=false"><UiIcon name="close"/></button></header><button @click="accountOpen=false;emit('settings')"><UiIcon name="settings"/>{{tr("设置")}}</button><label v-if="authMode==='demo'">{{tr("演示身份")}}<select :aria-label="tr('演示身份')" :value="actor" :disabled="run.inputLocked" @change="emit('actor',($event.target as HTMLSelectElement).value as ActorRole)"><option value="admin">{{tr("管理员")}}</option><option value="volunteer">{{tr("志愿者")}}</option><option value="student">{{tr("学生")}}</option></select></label><button @click="detailsOpen=!detailsOpen">{{tr("连接与模型")}}</button><div v-if="detailsOpen" class="sidebar-diagnostics"><BusinessConnectionPanel :unified="authMode==='native'"/><SourceBadge :source-type="run.sourceType??run.overviewSourceType" :engine="run.activeEngine" :model="run.model" compact/></div><button v-if="authMode==='native'" @click="emit('logout');accountOpen=false">{{tr("退出登录")}}</button></section></div></Teleport>
</template>
<style scoped>
