idth:100%;text-align:left}.sidebar-avatar{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--primary);color:var(--primary-contrast);flex-shrink:0;font-size:calc(var(--ui-font-size) * 0.84615)}.sidebar-account-name{display:flex;flex:1;flex-direction:column;min-width:0}.sidebar-account-name b{font-size:calc(var(--ui-font-size) * 0.92308);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.sidebar-account-name small{font-size:calc(var(--ui-font-size) * 0.76923);color:var(--text-muted)}.sidebar-resizer{position:absolute;right:0;top:0;bottom:0;width:8px;cursor:col-resize;touch-action:none;z-index:3}.sidebar-resizer:hover,.is-resizing .sidebar-resizer{background:var(--border-strong)}.is-collapsed .sidebar-brand{padding:2px 0 12px;justify-content:center}.is-collapsed .sidebar-brand>b,.is-collapsed .sidebar-brand>svg,.is-collapsed .sidebar-search,.is-collapsed .sidebar-history,.is-collapsed .sidebar-account-name,.is-collapsed .sidebar-account>svg{display:none}.is-collapsed .sidebar-brand button{margin:0}.is-collapsed .sidebar-tools :deep(.nav-tool),.is-collapsed .sidebar-link,.is-collapsed .sidebar-new,.is-collapsed .sidebar-search-icon{justify-content:center;padding:8px 0;min-height:38px}.is-collapsed .sidebar-tools :deep(.nav-tool span),.is-collapsed .sidebar-link span,.is-collapsed .sidebar-new span,.is-collapsed .sidebar-search-icon span{display:none}.is-collapsed .sidebar-search-icon{display:flex}.is-collapsed .sidebar-footer{margin-top:auto}.is-collapsed .sidebar-account{justify-content:center;padding:8px 0}.sidebar-account-mask{position:fixed;inset:0;background:#0002;z-index:110}.sidebar-account-menu{position:absolute;left:calc(var(--sidebar-size) + 8px);bottom:16px;width:min(290px,calc(100vw - 24px));max-height:calc(100dvh - 32px);overflow:auto;background:var(--surface);color:var(--text);border:1px solid var(--border-strong);border-radius:8px;box-shadow:var(--shadow-2);padding:10px}.sidebar-account-menu header{display:fl